        [IntelligencePromptCodes.WideLlmOnlyAnswer]=("Wide LLM-only answer",WideLlmOnlyAnswer),
        [IntelligencePromptCodes.WideLlmRawAnswer]=("Wide raw LLM ranking",WideLlmRawAnswer),
        [IntelligencePromptCodes.WideIntent]=("Wide intent proposal",WideIntent),
        [IntelligencePromptCodes.WideHierarchyStep]=("Wide hierarchy step",WideHierarchyStep),
        [IntelligencePromptCodes.WideAnswer]=("Wide final answer",WideAnswer),
        [IntelligencePromptCodes.WideQueryContract]=("Wide query contract",WideQueryContract),
        [IntelligencePromptCodes.WideCandidateEnumeration]=("Wide candidate enumeration",WideCandidateEnumeration),
        [IntelligencePromptCodes.WideChallengeRound]=("Wide challenge round",WideChallengeRound),
        [IntelligencePromptCodes.WideInformationValue]=("Wide information value",WideInformationValue),
        [IntelligencePromptCodes.WideCandidateMatrix]=("Wide candidate matrix",WideCandidateMatrix),
        [IntelligencePromptCodes.WidePoloxiExplanation]=("Wide POLOXI evidence explanation",WidePoloxiExplanation),
        [IntelligencePromptCodes.WidePoloxiHierarchy]=("Wide POLOXI hierarchy proposal",WidePoloxiHierarchy),
        [IntelligencePromptCodes.SearchSummary]=("Search evidence summary",SearchSummary),
        [IntelligencePromptCodes.PoloxiExplanation]=("POLOXI evidence explanation",PoloxiExplanation),
        [IntelligencePromptCodes.PoloxiHierarchy]=("POLOXI hierarchy proposal",PoloxiHierarchy),
        [IntelligencePromptCodes.SearchIntent]=("Search intent interpretation",SearchIntent),
    };
}
